const angular = require('angular');
require('angular-mocks');
require('../src/task.controller.js');

describe('TaskController', function () {
  var $controller;
  var TaskService;
  var $controllerProvider;

  beforeEach(angular.mock.module('taskApp'));

  beforeEach(inject(function (_$controller_, _TaskService_) {
    $controller = _$controller_;
    TaskService = _TaskService_;
  }));

  function createController() {
    return $controller('TaskController', { TaskService: TaskService });
  }

  beforeEach(function () {
    jest.spyOn(TaskService, 'list').mockReturnValue([{ id: 1, title: 'Test Task', done: false }]);
    jest.spyOn(TaskService, 'add');
    jest.spyOn(TaskService, 'remove');
    jest.spyOn(TaskService, 'save');
  });

  afterEach(function () {
    jest.restoreAllMocks();
  });

  test('should initialize with default values', function () {
    var vm = createController();
    expect(vm.tasks).toHaveLength(1);
    expect(vm.filter).toBe('all');
    expect(vm.error).toBe('');
  });

  test('should add a task successfully', function () {
    var vm = createController();
    vm.title = 'New Task';
    TaskService.add.mockReturnValue([{ id: 1 }, { id: 2 }]);
    
    vm.add();
    
    expect(TaskService.add).toHaveBeenCalledWith(vm.tasks, 'New Task');
    expect(vm.tasks).toHaveLength(2);
    expect(vm.title).toBe('');
    expect(vm.error).toBe('');
  });

  test('should handle error when adding a task', function () {
    var vm = createController();
    TaskService.add.mockImplementation(() => { throw new Error('Add failed'); });
    
    vm.add();
    
    expect(vm.error).toBe('Add failed');
  });

  test('should remove a task successfully', function () {
    var vm = createController();
    TaskService.remove.mockReturnValue([]);
    
    vm.remove(1);
    
    expect(TaskService.remove).toHaveBeenCalledWith(vm.tasks, 1);
    expect(vm.tasks).toHaveLength(0);
    expect(vm.error).toBe('');
  });

  test('should handle error when removing a task', function () {
    var vm = createController();
    TaskService.remove.mockImplementation(() => { throw new Error('Remove failed'); });
    
    vm.remove(1);
    
    expect(vm.error).toBe('Remove failed');
  });

  test('should toggle task status successfully', function () {
    var vm = createController();
    var task = { id: 1, done: false };
    
    vm.toggle(task);
    
    expect(TaskService.save).toHaveBeenCalled();
    expect(vm.error).toBe('');
  });

  test('should revert task status on toggle error', function () {
    var vm = createController();
    var task = { id: 1, done: false };
    TaskService.save.mockImplementation(() => { throw new Error('Save failed'); });
    
    vm.toggle(task);
    
    expect(task.done).toBe(true);
    expect(vm.error).toBe('Save failed');
  });

  test('should calculate completed tasks count', function () {
    var vm = createController();
    vm.tasks = [{ done: true }, { done: false }, { done: true }];
    expect(vm.completed()).toBe(2);
  });

  test('should filter tasks correctly', function () {
    var vm = createController();
    var task = { done: true };
    
    vm.filter = 'all';
    expect(vm.matches(task)).toBe(true);
    
    vm.filter = 'done';
    expect(vm.matches(task)).toBe(true);
    
    vm.filter = 'pending';
    expect(vm.matches(task)).toBe(false);
  });
});
